--
-- Name: admin_decide_wash_booking(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_decide_wash_booking(_wash_booking_id uuid, _decision text, _vendor_id uuid DEFAULT NULL::uuid, _note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b RECORD; refund numeric := 0;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admins only'; END IF;
  IF _decision NOT IN ('confirmed','rejected','completed') THEN RAISE EXCEPTION 'Invalid decision'; END IF;

  SELECT * INTO b FROM public.wash_bookings WHERE id = _wash_booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Wash booking not found'; END IF;

  IF _decision = 'confirmed' THEN
    IF _vendor_id IS NULL THEN RAISE EXCEPTION 'Assign a washer partner before approving'; END IF;
    UPDATE public.wash_bookings
       SET status = 'confirmed', assigned_vendor_id = _vendor_id,
           admin_note = NULLIF(btrim(COALESCE(_note,'')), ''), rejection_reason = NULL
     WHERE id = b.id;

  ELSIF _decision = 'rejected' THEN
    IF b.payment_status = 'paid' THEN
      refund := COALESCE(b.price, 0);
      PERFORM public.wallet_apply(b.customer_id, refund, 'wash_refund', NULL, b.id::text, 'Refund for rejected wash booking');
    END IF;
    UPDATE public.wash_bookings
       SET status = 'rejected',
           rejection_reason = NULLIF(btrim(COALESCE(_note,'')), ''),
           payment_status = CASE WHEN refund > 0 THEN 'refunded' ELSE b.payment_status END,
           refund_amount = refund,
           cancelled_at = now(), cancelled_by = auth.uid()
     WHERE id = b.id;

  ELSE
    IF b.status <> 'confirmed' THEN RAISE EXCEPTION 'Only approved washes can be completed'; END IF;
    IF b.payment_status <> 'paid' THEN RAISE EXCEPTION 'Payment is still pending for this wash'; END IF;
    UPDATE public.wash_bookings
       SET status = 'completed', completed_at = now(),
           admin_note = COALESCE(NULLIF(btrim(COALESCE(_note,'')), ''), b.admin_note)
     WHERE id = b.id;
  END IF;
END; $$;


--
-- Name: admin_decide_withdrawal(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_decide_withdrawal(_withdrawal_id uuid, _decision text, _reference text DEFAULT NULL::text, _note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE w RECORD;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admins only'; END IF;
  SELECT * INTO w FROM public.withdrawals WHERE id = _withdrawal_id FOR UPDATE;
  IF w IS NULL THEN RAISE EXCEPTION 'Withdrawal not found'; END IF;
  IF w.status <> 'requested' THEN RAISE EXCEPTION 'This withdrawal was already processed'; END IF;

  IF _decision = 'paid' THEN
    IF COALESCE(btrim(_reference), '') = '' THEN RAISE EXCEPTION 'Enter the payment reference (UTR)'; END IF;
    UPDATE public.withdrawals
       SET status = 'paid', reference = btrim(_reference), admin_note = NULLIF(btrim(COALESCE(_note, '')), ''),
           processed_at = now(), processed_by = auth.uid()
     WHERE id = w.id;
    PERFORM public.notify_user(w.user_id, 'Payout sent',
      'Rs ' || w.amount || ' has been paid out. Reference ' || btrim(_reference) || '.', '/wallet');
  ELSIF _decision = 'rejected' THEN
    UPDATE public.withdrawals
       SET status = 'rejected', admin_note = NULLIF(btrim(COALESCE(_note, '')), ''),
           processed_at = now(), processed_by = auth.uid()
     WHERE id = w.id;
    PERFORM public.wallet_apply(w.user_id, w.amount, 'payout_reversal', NULL, w.id::text, 'Withdrawal rejected — amount returned');
    PERFORM public.notify_user(w.user_id, 'Withdrawal rejected',
      COALESCE(NULLIF(btrim(COALESCE(_note, '')), ''), 'The amount is back in your wallet.'), '/wallet');
  ELSE
    RAISE EXCEPTION 'Decision must be paid or rejected';
  END IF;
END; $$;


