--
-- Name: admin_grant_credit(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_grant_credit(_email text, _amount numeric, _note text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE uid uuid; bal numeric;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admins only'; END IF;
  IF COALESCE(_amount, 0) <= 0 OR _amount > 100000 THEN RAISE EXCEPTION 'Amount must be between 1 and 100000'; END IF;
  SELECT id INTO uid FROM auth.users WHERE lower(email) = lower(btrim(_email)) LIMIT 1;
  IF uid IS NULL THEN RAISE EXCEPTION 'No user with that email'; END IF;
  bal := public.wallet_apply(uid, round(_amount, 2), 'promo_credit', NULL, NULL,
           COALESCE(NULLIF(btrim(COALESCE(_note, '')), ''), 'Promotional credit'));
  RETURN bal;
END; $$;


--
-- Name: admin_refund(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_refund(_email text, _amount numeric, _reason text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE uid uuid; why text := NULLIF(btrim(COALESCE(_reason, '')), '');
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admins only'; END IF;
  IF COALESCE(_amount, 0) <= 0 OR _amount > 100000 THEN RAISE EXCEPTION 'Amount must be between 1 and 100000'; END IF;
  IF why IS NULL THEN RAISE EXCEPTION 'A reason is required'; END IF;
  SELECT id INTO uid FROM auth.users WHERE lower(email) = lower(btrim(_email)) LIMIT 1;
  IF uid IS NULL THEN RAISE EXCEPTION 'No user with that email'; END IF;
  RETURN public.wallet_apply(uid, round(_amount, 2), 'refund', NULL, NULL, left('Admin refund: ' || why, 300));
END; $$;


