--
-- Name: admin_revenue_aggregates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_revenue_aggregates() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_rental_vol numeric;
  v_driver_vol numeric;
  v_wash_vol numeric;
  v_pool_vol numeric;
  v_gmv numeric;
  v_payouts numeric;
  v_refunds numeric;
  v_settings record;
  v_platform_rev numeric;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Admins only';
  END IF;

  SELECT * INTO v_settings FROM public.platform_settings WHERE id = 1;

  -- 1. Rentals volume
  SELECT COALESCE(SUM(total_price), 0) INTO v_rental_vol
  FROM public.bookings
  WHERE payment_status = 'paid' OR status = 'completed';

  -- 2. Driver hires volume
  SELECT COALESCE(SUM(total_price), 0) INTO v_driver_vol
  FROM public.driver_bookings
  WHERE payment_status = 'paid' OR status = 'completed';

  -- 3. Washes volume
  SELECT COALESCE(SUM(price), 0) INTO v_wash_vol
  FROM public.wash_bookings
  WHERE payment_status = 'paid' OR status = 'completed';

  -- 4. Carpooling volume
  SELECT COALESCE(SUM(pt.fare_per_seat * pr.seats), 0) INTO v_pool_vol
  FROM public.pool_requests pr
  JOIN public.pool_trips pt ON pr.trip_id = pt.id
  WHERE pr.status IN ('confirmed', 'completed');

  v_gmv := v_rental_vol + v_driver_vol + v_wash_vol + v_pool_vol;

  -- Disbursed payouts to providers
  SELECT COALESCE(SUM(amount), 0) INTO v_payouts
  FROM public.payouts
  WHERE status = 'paid';

  -- Total refunds issued
  SELECT (
    COALESCE((SELECT SUM(refund_amount) FROM public.bookings WHERE refund_amount > 0), 0) +
    COALESCE((SELECT SUM(refund_amount) FROM public.driver_bookings WHERE refund_amount > 0), 0) +
    COALESCE((SELECT SUM(refund_amount) FROM public.wash_bookings WHERE refund_amount > 0), 0)
  ) INTO v_refunds;

  -- Platform net revenue from commissions
  v_platform_rev := round(
    (v_rental_vol * COALESCE(v_settings.commission_rental_pct, 10) / 100.0) +
    (v_driver_vol * COALESCE(v_settings.commission_driver_pct, 10) / 100.0) +
    (v_wash_vol * COALESCE(v_settings.commission_wash_pct, 15) / 100.0) +
    (v_pool_vol * COALESCE(v_settings.commission_pool_pct, 5) / 100.0),
    2
  );

  RETURN jsonb_build_object(
    'gmv', v_gmv,
    'platform_revenue', v_platform_rev,
    'provider_payouts', v_payouts,
    'refunds', v_refunds,
    'rentals_volume', v_rental_vol,
    'driver_volume', v_driver_vol,
    'wash_volume', v_wash_vol,
    'pool_volume', v_pool_vol
  );
END;
$$;


--
-- Name: advance_wash_status(uuid, text, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.advance_wash_status(_wash_booking_id uuid, _next_status text, _photos text[] DEFAULT NULL::text[], _notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  b RECORD;
  is_admin boolean;
  is_assigned boolean;
  current_step integer;
  next_step integer;
  norm_next text;
  norm_curr text;
  new_before text[];
  new_after text[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO b FROM public.wash_bookings WHERE id = _wash_booking_id FOR UPDATE;
  IF b IS NULL THEN
    RAISE EXCEPTION 'Wash booking not found';
  END IF;

  is_admin := public.has_role(auth.uid(), 'admin');
  is_assigned := (b.assigned_cleaner_id = auth.uid())
    OR (b.assigned_vendor_id = auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.wash_vendors
      WHERE id = b.assigned_vendor_id AND (id = auth.uid() OR contact_email = (SELECT email FROM auth.users WHERE id = auth.uid()))
    );

  IF NOT is_admin AND NOT is_assigned THEN
    RAISE EXCEPTION 'You are not assigned to this wash job';
  END IF;

  norm_next := lower(btrim(_next_status));
  norm_curr := lower(btrim(COALESCE(b.progress::text, b.status::text, 'requested')));
  IF norm_curr = 'pending' THEN norm_curr := 'requested'; END IF;

  current_step := CASE norm_curr
    WHEN 'requested' THEN 1
    WHEN 'confirmed' THEN 2
    WHEN 'assigned' THEN 3
    WHEN 'on_the_way' THEN 4
    WHEN 'started' THEN 5
    WHEN 'completed' THEN 6
    ELSE 0
  END;

  next_step := CASE norm_next
    WHEN 'requested' THEN 1
    WHEN 'confirmed' THEN 2
    WHEN 'assigned' THEN 3
    WHEN 'on_the_way' THEN 4
    WHEN 'started' THEN 5
    WHEN 'completed' THEN 6
    ELSE -1
  END;

  IF next_step = -1 THEN
    RAISE EXCEPTION 'Invalid wash status: %', _next_status;
  END IF;

  IF next_step <= current_step THEN
    RAISE EXCEPTION 'Status cannot be moved backwards or to the same status (current: %, requested: %)', norm_curr, norm_next;
  END IF;

  new_before := COALESCE(b.before_photos, '{}');
  new_after := COALESCE(b.after_photos, '{}');

  IF norm_next = 'started' AND _photos IS NOT NULL THEN
    new_before := array_cat(new_before, _photos);
  ELSIF norm_next = 'completed' THEN
    IF _photos IS NOT NULL THEN
      new_after := array_cat(new_after, _photos);
    END IF;
    IF COALESCE(array_length(new_after, 1), 0) = 0 THEN
      RAISE EXCEPTION 'After photos are required to complete the wash';
    END IF;
  END IF;

  UPDATE public.wash_bookings
     SET progress = norm_next::public.wash_status,
         status = CASE
           WHEN norm_next IN ('confirmed', 'completed', 'cancelled', 'rejected') THEN norm_next::public.booking_status
           WHEN norm_next = 'requested' THEN 'pending'::public.booking_status
           ELSE b.status
         END,
         before_photos = new_before,
         after_photos = new_after,
         completed_at = CASE WHEN norm_next = 'completed' THEN now() ELSE b.completed_at END,
         notes = COALESCE(NULLIF(btrim(_notes), ''), b.notes),
         updated_at = now()
   WHERE id = b.id;

  RETURN jsonb_build_object(
    'id', b.id,
    'progress', norm_next,
    'status', norm_next,
    'before_photos', new_before,
    'after_photos', new_after
  );
END;
$$;


--
-- Name: apply_referral_bonus_on_first_paid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_referral_bonus_on_first_paid() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ref_user uuid;
  v_rewarded boolean;
  v_prior_paid_count int;
BEGIN
  IF NEW.payment_status = 'paid' AND (OLD.payment_status IS DISTINCT FROM 'paid') THEN
    SELECT referred_by, referral_rewarded INTO v_ref_user, v_rewarded
    FROM public.profiles
    WHERE id = NEW.customer_id;

    IF v_ref_user IS NOT NULL AND NOT COALESCE(v_rewarded, false) THEN
      -- Verify this is their first paid booking
      SELECT count(*) INTO v_prior_paid_count
      FROM public.bookings
      WHERE customer_id = NEW.customer_id AND payment_status = 'paid' AND id != NEW.id;

      IF v_prior_paid_count = 0 THEN
        -- Credit referrer ₹500
        PERFORM public.wallet_apply(v_ref_user, 500, 'referral_bonus');
        INSERT INTO public.notifications (user_id, title, body, link)
        VALUES (v_ref_user, 'Referral Bonus Credited', '₹500 added to your wallet! A friend completed their first ride.', '/wallet');

        -- Credit friend ₹500
        PERFORM public.wallet_apply(NEW.customer_id, 500, 'referral_bonus');
        INSERT INTO public.notifications (user_id, title, body, link)
        VALUES (NEW.customer_id, 'Welcome Bonus Credited', '₹500 referral credit added to your wallet!', '/wallet');

        -- Mark rewarded so it only fires once
        UPDATE public.profiles SET referral_rewarded = true WHERE id = NEW.customer_id;
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: booked_vehicle_ids(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.booked_vehicle_ids(_start date, _end date) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT DISTINCT b.vehicle_id
  FROM public.bookings b
  WHERE b.status IN ('pending','confirmed')
    AND b.start_date <= _end
    AND b.end_date >= _start
  UNION
  SELECT DISTINCT a.vehicle_id
  FROM public.availability_blocks a
  WHERE a.start_date <= _end
    AND a.end_date >= _start;
$$;


--
-- Name: can_access_booking_folder(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_booking_folder(_folder text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.id::text = _folder
      AND (b.customer_id = auth.uid() OR b.vendor_id = auth.uid())
  ) OR public.has_role(auth.uid(), 'admin');
$$;


