-- Name: can_read_vehicle_image(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_vehicle_image(_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.vehicles v
    WHERE v.id::text = (storage.foldername(_name))[2]
      AND (
        (v.status = 'active' AND v.verification_status = 'approved')
        OR v.vendor_id = auth.uid()
        OR public.has_role(auth.uid(), 'admin')
      )
  );
$$;


--
-- Name: cancel_booking(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_booking(_booking_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  b RECORD; starts_at timestamptz; hours_left numeric; pct numeric := 0;
  refund numeric := 0; share numeric := 0; by_provider boolean; is_admin boolean; new_pay text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.bookings WHERE id = _booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;

  is_admin := public.has_role(auth.uid(), 'admin');
  by_provider := (b.vendor_id = auth.uid());
  IF NOT is_admin AND NOT by_provider AND b.customer_id <> auth.uid() THEN
    RAISE EXCEPTION 'Not your booking';
  END IF;
  IF b.status IN ('cancelled','rejected','completed') THEN
    RAISE EXCEPTION 'This booking can no longer be cancelled';
  END IF;
  IF b.pickup_checked_at IS NOT NULL AND NOT is_admin THEN
    RAISE EXCEPTION 'The trip has started — raise a dispute instead';
  END IF;

  starts_at := (b.start_date::timestamp + b.pickup_time) AT TIME ZONE 'Asia/Kolkata';
  hours_left := EXTRACT(EPOCH FROM (starts_at - now())) / 3600.0;

  IF b.payment_status = 'paid' THEN
    IF is_admin OR by_provider OR hours_left >= 24 THEN pct := 1;
    ELSIF hours_left >= 2 THEN pct := 0.5;
    ELSE pct := 0; END IF;
    refund := b.security_deposit + round((b.total_price - b.security_deposit) * pct, 2);
    share := round(b.provider_earning * (1 - pct), 2);

    IF refund > 0 THEN
      PERFORM public.wallet_apply(b.customer_id, refund, 'refund', b.id, NULL,
        CASE WHEN pct = 1 THEN 'Full refund for cancelled booking' ELSE 'Partial refund for cancelled booking' END);
    END IF;
    IF share > 0 AND b.vendor_id <> b.customer_id AND b.earning_credited_at IS NULL THEN
      PERFORM public.wallet_apply(b.vendor_id, share, 'booking_earning', b.id, NULL,
        'Late-cancellation share (after commission)');
    END IF;
    new_pay := CASE WHEN pct = 1 THEN 'refunded' ELSE 'partially_refunded' END;
  ELSE
    new_pay := b.payment_status;
  END IF;

  UPDATE public.bookings
     SET status = 'cancelled', payment_status = new_pay, refund_amount = refund,
         earning_credited_at = CASE WHEN b.payment_status = 'paid' THEN now() ELSE earning_credited_at END,
         cancelled_at = now(), cancelled_by = auth.uid(),
         cancellation_reason = NULLIF(btrim(COALESCE(_reason, '')), '')
   WHERE id = b.id;

  RETURN jsonb_build_object('refund', refund, 'percent', pct * 100, 'provider_share', share,
                            'payment_status', new_pay, 'cancelled_by_provider', by_provider);
END; $$;


--
-- Name: cancel_booking_extension(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_booking_extension(_extension_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e RECORD;
BEGIN
  SELECT * INTO e FROM public.booking_extensions WHERE id = _extension_id FOR UPDATE;
  IF e IS NULL THEN RAISE EXCEPTION 'Extension not found'; END IF;
  IF e.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your request'; END IF;
  IF e.status NOT IN ('pending','accepted') THEN RAISE EXCEPTION 'This request is already closed'; END IF;
  UPDATE public.booking_extensions SET status = 'cancelled', decided_at = now() WHERE id = e.id;
END; $$;


--
-- Name: cancel_driver_booking(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_driver_booking(_driver_booking_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  b RECORD; starts_at timestamptz; hours_left numeric; pct numeric := 0;
  refund numeric := 0; share numeric := 0; is_driver boolean; is_admin boolean; new_pay_status text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.driver_bookings WHERE id = _driver_booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Hire not found'; END IF;

  is_admin := public.has_role(auth.uid(), 'admin');
  is_driver := (b.driver_id = auth.uid());
  IF NOT is_admin AND NOT is_driver AND b.customer_id <> auth.uid() THEN
    RAISE EXCEPTION 'Not your booking';
  END IF;
  IF b.status IN ('cancelled','rejected','completed') THEN
    RAISE EXCEPTION 'This hire can no longer be cancelled';
  END IF;

  starts_at := (b.start_date::timestamp + b.start_time) AT TIME ZONE 'Asia/Kolkata';
  hours_left := EXTRACT(EPOCH FROM (starts_at - now())) / 3600.0;

  IF b.payment_status = 'paid' THEN
    IF is_admin OR is_driver OR hours_left >= 24 THEN pct := 1;
    ELSIF hours_left >= 2 THEN pct := 0.5;
    ELSE pct := 0; END IF;
    refund := round(COALESCE(b.total_price, 0) * pct, 2);
    share := round(b.provider_earning * (1 - pct), 2);

    IF refund > 0 THEN
      PERFORM public.wallet_apply(b.customer_id, refund, 'driver_refund', NULL, b.id::text,
        CASE WHEN pct = 1 THEN 'Full refund for cancelled driver hire' ELSE 'Partial refund for cancelled driver hire' END);
    END IF;
    IF share > 0 AND b.driver_id <> b.customer_id AND b.earning_credited_at IS NULL THEN
      PERFORM public.wallet_apply(b.driver_id, share, 'driver_earning', NULL, b.id::text,
        'Late-cancellation share (after commission)');
    END IF;
    new_pay_status := CASE WHEN pct = 1 THEN 'refunded' ELSE 'partially_refunded' END;
  ELSE
    new_pay_status := b.payment_status;
  END IF;

  UPDATE public.driver_bookings
     SET status = 'cancelled', payment_status = new_pay_status, refund_amount = refund,
         earning_credited_at = CASE WHEN b.payment_status = 'paid' THEN now() ELSE earning_credited_at END,
         cancelled_at = now(), cancelled_by = auth.uid(),
         cancellation_reason = NULLIF(btrim(COALESCE(_reason, '')), '')
   WHERE id = b.id;

  RETURN jsonb_build_object('refund', refund, 'percent', pct * 100, 'provider_share', share,
                            'payment_status', new_pay_status, 'cancelled_by_driver', is_driver);
END; $$;


--
-- Name: cancel_wash_booking(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_wash_booking(_wash_booking_id uuid, _reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  b RECORD; starts_at timestamptz; hours_left numeric; pct numeric := 0;
  refund numeric := 0; is_admin boolean; new_pay text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.wash_bookings WHERE id = _wash_booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Wash booking not found'; END IF;

  is_admin := public.has_role(auth.uid(), 'admin');
  IF NOT is_admin AND b.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your booking'; END IF;
  IF b.status IN ('cancelled','rejected','completed') THEN RAISE EXCEPTION 'This wash can no longer be cancelled'; END IF;

  starts_at := (b.slot_date::timestamp + b.slot_time) AT TIME ZONE 'Asia/Kolkata';
  hours_left := EXTRACT(EPOCH FROM (starts_at - now())) / 3600.0;

  IF b.payment_status = 'paid' THEN
    IF is_admin OR hours_left >= 24 THEN pct := 1;
    ELSIF hours_left >= 2 THEN pct := 0.5;
    ELSE pct := 0; END IF;
    refund := ROUND(COALESCE(b.price, 0) * pct, 2);
  END IF;

  IF refund > 0 THEN
    PERFORM public.wallet_apply(b.customer_id, refund, 'wash_refund', NULL, b.id::text,
      CASE WHEN pct = 1 THEN 'Full refund for cancelled wash' ELSE 'Partial refund for cancelled wash' END);
    new_pay := CASE WHEN pct = 1 THEN 'refunded' ELSE 'partially_refunded' END;
  ELSE
    new_pay := b.payment_status;
  END IF;

  UPDATE public.wash_bookings
     SET status = 'cancelled', payment_status = new_pay, refund_amount = refund,
         cancelled_at = now(), cancelled_by = auth.uid(),
         cancellation_reason = NULLIF(btrim(COALESCE(_reason,'')), '')
   WHERE id = b.id;

  RETURN jsonb_build_object('refund', refund, 'percent', pct * 100, 'payment_status', new_pay);
END; $$;


--
-- Name: claim_wash_job(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_wash_job(_wash_booking_id uuid DEFAULT NULL::uuid, id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _target_id uuid;
  _cleaner record;
  _booking record;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  _target_id := COALESCE(_wash_booking_id, id);
  IF _target_id IS NULL THEN
    RAISE EXCEPTION 'Wash booking ID is required';
  END IF;

  -- 1. Verify cleaner profile and approved status
  SELECT * INTO _cleaner
    FROM public.cleaners
   WHERE id = auth.uid();

  IF _cleaner IS NULL THEN
    RAISE EXCEPTION 'Cleaner profile not found';
  END IF;

  IF _cleaner.verification_status != 'approved' THEN
    RAISE EXCEPTION 'Only verified cleaners can claim jobs';
  END IF;

  -- 2. Lock the wash booking row atomically to prevent race conditions / double claiming (CJ-01)
  SELECT * INTO _booking
    FROM public.wash_bookings
   WHERE id = _target_id
     FOR UPDATE;

  IF _booking IS NULL THEN
    RAISE EXCEPTION 'Wash booking not found';
  END IF;

  -- 3. Check if already claimed or assigned
  IF _booking.assigned_cleaner_id IS NOT NULL OR _booking.assigned_vendor_id IS NOT NULL THEN
    RAISE EXCEPTION 'This wash job is already assigned';
  END IF;

  -- 4. Check if confirmed (must be confirmed)
  IF _booking.status != 'confirmed' AND _booking.progress != 'confirmed' THEN
    RAISE EXCEPTION 'Only confirmed wash jobs can be claimed';
  END IF;

  -- 5. Check city match (case-insensitive) (CJ-02)
  IF lower(trim(_cleaner.city)) != lower(trim(_booking.city)) THEN
    RAISE EXCEPTION 'Cleaner cannot claim jobs outside their operating city (cleaner city: %, job city: %)', _cleaner.city, _booking.city;
  END IF;

  -- 6. Atomically assign job to cleaner
  UPDATE public.wash_bookings
     SET assigned_cleaner_id = auth.uid(),
         progress = 'assigned',
         status = 'confirmed',
         updated_at = now()
   WHERE id = _target_id;

  -- 7. Notify customer
  INSERT INTO public.notifications (user_id, title, body, link)
  VALUES (
    _booking.customer_id,
    'Cleaner Assigned to Your Wash',
    _cleaner.full_name || ' has claimed your wash booking and will arrive at your scheduled slot.',
    '/washes'
  );

  RETURN jsonb_build_object(
    'id', _booking.id,
    'assigned_cleaner_id', auth.uid(),
    'progress', 'assigned',
    'status', 'confirmed',
    'cleaner_name', _cleaner.full_name
  );
END;
$$;


--
-- Name: compute_charges(numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_charges(_base numeric, _coupon text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  s RECORD; c RECORD; disc numeric := 0; fee numeric; gst numeric; comm numeric; comm_gst numeric;
  coupon_norm text := NULLIF(upper(btrim(COALESCE(_coupon, ''))), '');
BEGIN
  IF _base IS NULL OR _base < 0 THEN RAISE EXCEPTION 'Invalid amount'; END IF;
  SELECT * INTO s FROM public.platform_settings WHERE id = 1;

  IF coupon_norm IS NOT NULL THEN
    SELECT * INTO c FROM public.coupons
     WHERE upper(btrim(coupons.code)) = coupon_norm AND active
       AND (starts_at IS NULL OR starts_at <= now())
       AND (ends_at IS NULL OR ends_at >= now())
     LIMIT 1;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invalid or expired coupon'; END IF;
    disc := CASE WHEN c.percent_off IS NOT NULL THEN _base * c.percent_off / 100.0
                 ELSE COALESCE(c.amount_off, 0) END;
    disc := round(LEAST(_base, GREATEST(disc, 0)), 2);
  END IF;

  fee := round((_base - disc) * COALESCE(s.service_fee_pct, 0) / 100.0, 2);
  gst := round(fee * COALESCE(s.gst_pct, 0) / 100.0, 2);
  comm := round(_base * COALESCE(s.commission_pct, 0) / 100.0, 2);
  comm_gst := round(comm * COALESCE(s.gst_pct, 0) / 100.0, 2);

  RETURN jsonb_build_object(
    'base', _base,
    'coupon_code', coupon_norm,
    'discount', disc,
    'service_fee', fee,
    'gst', gst,
    'commission', comm,
    'commission_gst', comm_gst,
    'provider_earning', _base - comm - comm_gst,
    'customer_total', _base - disc + fee + gst
  );
END; $$;


--
-- Name: decide_booking_extension(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.decide_booking_extension(_extension_id uuid, _accept boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e RECORD;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO e FROM public.booking_extensions WHERE id = _extension_id FOR UPDATE;
  IF e IS NULL THEN RAISE EXCEPTION 'Extension not found'; END IF;
  IF e.vendor_id <> auth.uid() THEN RAISE EXCEPTION 'Only the host can decide'; END IF;
  IF e.status <> 'pending' THEN RAISE EXCEPTION 'This request was already decided'; END IF;
  IF _accept AND public.extension_clashes(e.booking_id, e.new_end_date) THEN
    RAISE EXCEPTION 'The vehicle is booked or blocked during the extra time';
  END IF;

  UPDATE public.booking_extensions
     SET status = CASE WHEN _accept THEN 'accepted' ELSE 'rejected' END, decided_at = now()
   WHERE id = e.id;

  PERFORM public.notify_user(e.customer_id,
    CASE WHEN _accept THEN 'Extension accepted' ELSE 'Extension declined' END,
    CASE WHEN _accept THEN 'Pay from your wallet to confirm the extra ' || e.hours || 'h.'
         ELSE 'Your host could not extend this trip. Please return on time.' END,
    '/bookings/' || e.booking_id || '/trip');
  RETURN CASE WHEN _accept THEN 'accepted' ELSE 'rejected' END;
END; $$;


--
-- Name: delete_my_account_data(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_my_account_data() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  uid uuid := auth.uid();
  open_count int := 0;
BEGIN
  IF uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_authenticated');
  END IF;

  SELECT count(*) INTO open_count FROM (
    SELECT 1 FROM public.bookings WHERE (customer_id = uid OR vendor_id = uid) AND status IN ('pending','confirmed')
    UNION ALL
    SELECT 1 FROM public.driver_bookings WHERE customer_id = uid AND status IN ('pending','confirmed')
    UNION ALL
    SELECT 1 FROM public.wash_bookings WHERE customer_id = uid AND status IN ('pending','confirmed')
  ) s;

  IF open_count > 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'open_bookings', 'count', open_count);
  END IF;

  DELETE FROM public.wishlists WHERE user_id = uid;
  DELETE FROM public.notifications WHERE user_id = uid;

  UPDATE public.profiles SET
    full_name = 'Deleted user',
    avatar_url = NULL,
    phone = NULL,
    city = NULL,
    dl_number = NULL,
    dl_expiry = NULL,
    dl_front_url = NULL,
    dl_back_url = NULL,
    dl_status = 'none',
    dl_rejection_reason = NULL,
    dl_verified_at = NULL,
    updated_at = now()
  WHERE id = uid;

  UPDATE public.vendors SET
    business_name = 'Deleted host',
    bio = NULL,
    payout_email = NULL,
    id_document_url = NULL,
    updated_at = now()
  WHERE id = uid;

  UPDATE public.vehicles SET status = 'paused', updated_at = now() WHERE vendor_id = uid;

  UPDATE public.drivers SET
    full_name = 'Deleted driver',
    phone = NULL,
    bio = NULL,
    photo_url = NULL,
    dl_number = NULL,
    dl_expiry = NULL,
    dl_front_url = NULL,
    dl_back_url = NULL,
    id_document_url = NULL,
    status = 'paused',
    updated_at = now()
  WHERE id = uid;

  UPDATE public.pool_trips SET status = 'cancelled', updated_at = now()
  WHERE driver_id = uid AND depart_at > now() AND status <> 'cancelled';

  RETURN jsonb_build_object('ok', true);
END;
$$;


--
-- Name: driver_base_price(uuid, text, date, date, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.driver_base_price(_driver_id uuid, _rate_type text, _start_date date, _end_date date, _start time without time zone, _end time without time zone, OUT base numeric, OUT billed_hours integer, OUT billed_days integer) RETURNS record
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d RECORD; raw_hours numeric;
BEGIN
  SELECT hourly_rate, daily_rate INTO d FROM public.drivers WHERE id = _driver_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Driver not found'; END IF;
  IF _start_date IS NULL OR _end_date IS NULL OR _end_date < _start_date THEN
    RAISE EXCEPTION 'Pick valid dates';
  END IF;
  billed_days := (_end_date - _start_date) + 1;
  raw_hours := GREATEST(0, EXTRACT(EPOCH FROM ((_end_date + _end) - (_start_date + _start))) / 3600.0);

  IF _rate_type = 'hourly' THEN
    IF COALESCE(d.hourly_rate, 0) <= 0 THEN RAISE EXCEPTION 'This driver does not offer hourly hire'; END IF;
    IF billed_days > 1 THEN RAISE EXCEPTION 'Hourly hire must start and end on the same day'; END IF;
    billed_hours := ceil(raw_hours);
    IF billed_hours <= 0 THEN RAISE EXCEPTION 'End time must be after start time'; END IF;
    base := billed_hours * d.hourly_rate;
    RETURN;
  END IF;

  IF COALESCE(d.daily_rate, 0) <= 0 THEN RAISE EXCEPTION 'Daily rate unavailable'; END IF;
  billed_hours := ceil(raw_hours);
  base := billed_days * d.daily_rate;
END; $$;


--
-- Name: enforce_booking_update_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_booking_update_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_end_user_request() THEN RETURN NEW; END IF;
  IF public.has_role(auth.uid(), 'admin') THEN RETURN NEW; END IF;

  -- Immutable identity / schedule / money / payment / handover columns
  NEW.id := OLD.id;
  NEW.vehicle_id := OLD.vehicle_id;
  NEW.vendor_id := OLD.vendor_id;
  NEW.customer_id := OLD.customer_id;
  NEW.start_date := OLD.start_date;
  NEW.end_date := OLD.end_date;
  NEW.pickup_time := OLD.pickup_time;
  NEW.dropoff_time := OLD.dropoff_time;
  NEW.base_price := OLD.base_price;
  NEW.security_deposit := OLD.security_deposit;
  NEW.discount := OLD.discount;
  NEW.total_price := OLD.total_price;
  NEW.coupon_code := OLD.coupon_code;
  NEW.payment_status := OLD.payment_status;
  NEW.payment_method := OLD.payment_method;
  NEW.razorpay_order_id := OLD.razorpay_order_id;
  NEW.razorpay_payment_id := OLD.razorpay_payment_id;
  NEW.paid_at := OLD.paid_at;
  NEW.qr_code := OLD.qr_code;
  NEW.pickup_checked_at := OLD.pickup_checked_at;
  NEW.return_checked_at := OLD.return_checked_at;
  NEW.created_at := OLD.created_at;

  RETURN NEW;
END; $$;


--
-- Name: enforce_customer_dl_approved(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_customer_dl_approved() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE p RECORD;
BEGIN
  SELECT dl_status, dl_expiry INTO p FROM public.profiles WHERE id = NEW.customer_id;
  IF p.dl_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION 'Your driving licence must be approved before booking';
  END IF;
  IF p.dl_expiry IS NOT NULL AND p.dl_expiry < NEW.end_date THEN
    RAISE EXCEPTION 'Your driving licence expires before the booking end date';
  END IF;
  RETURN NEW;
END $$;


