--
-- Name: enforce_driver_review_update_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_driver_review_update_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_end_user_request() THEN RETURN NEW; END IF;
  IF public.has_role(auth.uid(), 'admin') OR OLD.customer_id = auth.uid() THEN RETURN NEW; END IF;

  -- The reviewed driver may only write a public response.
  IF NEW.rating IS DISTINCT FROM OLD.rating
     OR NEW.comment IS DISTINCT FROM OLD.comment
     OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.driver_id IS DISTINCT FROM OLD.driver_id
     OR NEW.driver_booking_id IS DISTINCT FROM OLD.driver_booking_id THEN
    RAISE EXCEPTION 'Drivers can only add a response to a review';
  END IF;

  NEW.id := OLD.id;
  NEW.created_at := OLD.created_at;
  IF NEW.driver_response IS DISTINCT FROM OLD.driver_response THEN
    NEW.driver_response_at := now();
  ELSE
    NEW.driver_response_at := OLD.driver_response_at;
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: FUNCTION enforce_driver_review_update_scope(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_driver_review_update_scope() IS 'Blocks drivers from changing a customer review rating/comment; only driver_response(_at) may change.';


--
-- Name: enforce_driver_verification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_driver_verification_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.has_role(auth.uid(), 'admin') THEN
    IF NEW.verification_status = 'approved' THEN
      NEW.verified_at = COALESCE(NEW.verified_at, now());
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.verification_status := 'pending';
    NEW.status := 'draft';
    NEW.verified_at := NULL;
    NEW.rejection_reason := NULL;
    NEW.avg_rating := 0;
    NEW.review_count := 0;
    RETURN NEW;
  END IF;

  -- Re-submitting documents sends the profile back for review
  IF (NEW.dl_front_url IS DISTINCT FROM OLD.dl_front_url)
     OR (NEW.dl_back_url IS DISTINCT FROM OLD.dl_back_url)
     OR (NEW.id_document_url IS DISTINCT FROM OLD.id_document_url)
     OR (NEW.dl_number IS DISTINCT FROM OLD.dl_number) THEN
    NEW.verification_status := 'pending';
    NEW.verified_at := NULL;
    NEW.rejection_reason := NULL;
  ELSE
    NEW.verification_status := OLD.verification_status;
    NEW.verified_at := OLD.verified_at;
    NEW.rejection_reason := OLD.rejection_reason;
  END IF;

  NEW.avg_rating := OLD.avg_rating;
  NEW.review_count := OLD.review_count;

  IF NEW.verification_status IS DISTINCT FROM 'approved' AND NEW.status = 'active' THEN
    NEW.status := OLD.status;
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: enforce_pool_request_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_pool_request_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE t public.pool_trips;
BEGIN
  SELECT * INTO t FROM public.pool_trips WHERE id = NEW.trip_id FOR UPDATE;
  IF t.id IS NULL THEN
    RAISE EXCEPTION 'Pool trip not found';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF t.driver_id = NEW.passenger_id THEN
      RAISE EXCEPTION 'You cannot join your own pool trip';
    END IF;
    IF t.status <> 'scheduled' OR t.depart_at <= now() THEN
      RAISE EXCEPTION 'This pool trip has already started or is closed';
    END IF;
    IF NEW.seats > t.seats_available THEN
      RAISE EXCEPTION 'Only % seat(s) left on this trip', t.seats_available;
    END IF;
    NEW.status := 'pending';
    NEW.fare_total := t.fare_per_seat * NEW.seats;
    RETURN NEW;
  END IF;

  NEW.trip_id := OLD.trip_id;
  NEW.passenger_id := OLD.passenger_id;
  NEW.seats := OLD.seats;
  NEW.fare_total := OLD.fare_total;
  NEW.match_score := OLD.match_score;

  IF NEW.status <> OLD.status THEN
    IF OLD.status IN ('rejected','cancelled','completed') THEN
      RAISE EXCEPTION 'This request is already closed';
    END IF;
    IF NEW.status = 'confirmed' THEN
      IF auth.uid() <> t.driver_id AND NOT public.has_role(auth.uid(), 'admin') THEN
        RAISE EXCEPTION 'Only the trip driver can accept passengers';
      END IF;
      IF t.seats_available < OLD.seats THEN
        RAISE EXCEPTION 'Not enough seats left to accept this request';
      END IF;
      PERFORM set_config('app.pool_seat_sync', '1', true);
      UPDATE public.pool_trips SET seats_available = seats_available - OLD.seats WHERE id = t.id;
      PERFORM set_config('app.pool_seat_sync', '0', true);
    ELSIF NEW.status = 'rejected' THEN
      IF auth.uid() <> t.driver_id AND NOT public.has_role(auth.uid(), 'admin') THEN
        RAISE EXCEPTION 'Only the trip driver can reject passengers';
      END IF;
    ELSIF NEW.status = 'cancelled' THEN
      IF OLD.status = 'confirmed' THEN
        PERFORM set_config('app.pool_seat_sync', '1', true);
        UPDATE public.pool_trips SET seats_available = LEAST(t.seats_total, t.seats_available + OLD.seats) WHERE id = t.id;
        PERFORM set_config('app.pool_seat_sync', '0', true);
      END IF;
      NEW.cancelled_by := auth.uid();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_pool_trip_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_pool_trip_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.depart_at <= now() THEN
      RAISE EXCEPTION 'Departure time must be in the future';
    END IF;
    NEW.seats_available := NEW.seats_total;
    NEW.status := 'scheduled';
  ELSE
    NEW.driver_id := OLD.driver_id;
    NEW.seats_total := OLD.seats_total;
    -- Seat counts may only change through the pool-request workflow.
    IF coalesce(current_setting('app.pool_seat_sync', true), '') <> '1' THEN
      NEW.seats_available := OLD.seats_available;
    ELSE
      NEW.seats_available := GREATEST(0, LEAST(NEW.seats_total, NEW.seats_available));
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_review_update_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_review_update_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.is_end_user_request() THEN RETURN NEW; END IF;
  IF public.has_role(auth.uid(), 'admin') OR OLD.customer_id = auth.uid() THEN RETURN NEW; END IF;

  -- Vendors may only change their public response fields.
  IF NEW.rating IS DISTINCT FROM OLD.rating
     OR NEW.comment IS DISTINCT FROM OLD.comment
     OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
     OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id
     OR NEW.booking_id IS DISTINCT FROM OLD.booking_id
     OR NEW.reported IS DISTINCT FROM OLD.reported
     OR NEW.report_reason IS DISTINCT FROM OLD.report_reason THEN
    RAISE EXCEPTION 'Hosts can only add a response to a review';
  END IF;

  NEW.id := OLD.id;
  NEW.created_at := OLD.created_at;
  IF NEW.vendor_response IS DISTINCT FROM OLD.vendor_response THEN
    NEW.vendor_response_at := now();
  ELSE
    NEW.vendor_response_at := OLD.vendor_response_at;
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: FUNCTION enforce_review_update_scope(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.enforce_review_update_scope() IS 'Blocks hosts from changing a customer review rating/comment/report fields; only vendor_response(_at) may change.';


--
-- Name: enforce_vehicle_verification_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_vehicle_verification_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.has_role(auth.uid(), 'admin') THEN
    IF NEW.verification_status = 'approved' AND OLD IS DISTINCT FROM NULL THEN
      NEW.verified_at = COALESCE(NEW.verified_at, now());
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.verification_status := 'pending';
    NEW.status := 'draft';
    NEW.verified_at := NULL;
    NEW.rejection_reason := NULL;
    RETURN NEW;
  END IF;

  NEW.verification_status := OLD.verification_status;
  NEW.verified_at := OLD.verified_at;
  NEW.rejection_reason := OLD.rejection_reason;

  IF OLD.verification_status IS DISTINCT FROM 'approved' AND NEW.status = 'active' THEN
    NEW.status := OLD.status;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_vendor_kyc_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_vendor_kyc_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF public.has_role(auth.uid(), 'admin') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.kyc_status := CASE WHEN NEW.id_document_url IS NULL THEN 'unsubmitted'::kyc_status ELSE 'pending'::kyc_status END;
    RETURN NEW;
  END IF;

  IF NEW.id_document_url IS DISTINCT FROM OLD.id_document_url AND NEW.id_document_url IS NOT NULL THEN
    NEW.kyc_status := 'pending'::kyc_status;
  ELSE
    NEW.kyc_status := OLD.kyc_status;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_wash_booking_forward_progress(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_wash_booking_forward_progress() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  curr_step integer;
  next_step integer;
  norm_curr text;
  norm_next text;
BEGIN
  IF (NEW.progress IS DISTINCT FROM OLD.progress OR NEW.status IS DISTINCT FROM OLD.status) THEN
    norm_curr := lower(btrim(COALESCE(OLD.progress::text, OLD.status::text, 'requested')));
    IF norm_curr = 'pending' THEN norm_curr := 'requested'; END IF;
    
    norm_next := lower(btrim(COALESCE(NEW.progress::text, NEW.status::text, norm_curr)));
    IF norm_next = 'pending' THEN norm_next := 'requested'; END IF;

    IF norm_next IN ('cancelled', 'rejected') THEN
      RETURN NEW;
    END IF;

    curr_step := CASE norm_curr
      WHEN 'requested' THEN 1
      WHEN 'confirmed' THEN 2
      WHEN 'assigned' THEN 3
      WHEN 'on_the_way' THEN 4
      WHEN 'started' THEN 5
      WHEN 'completed' THEN 6
      ELSE 0
    END;

    next_step := CASE norm_next
      WHEN 'requested' THEN 1
      WHEN 'confirmed' THEN 2
      WHEN 'assigned' THEN 3
      WHEN 'on_the_way' THEN 4
      WHEN 'started' THEN 5
      WHEN 'completed' THEN 6
      ELSE 0
    END;

    IF next_step > 0 AND curr_step > 0 AND next_step < curr_step THEN
      RAISE EXCEPTION 'Wash status cannot be moved backwards (current: %, requested: %)', norm_curr, norm_next;
    END IF;

    IF norm_next = 'completed' AND COALESCE(array_length(NEW.after_photos, 1), 0) = 0 THEN
      RAISE EXCEPTION 'After photos are required to complete the wash';
    END IF;

    -- Sync status and progress
    IF NEW.progress IS NOT DISTINCT FROM OLD.progress AND NEW.status IS DISTINCT FROM OLD.status THEN
      IF norm_next IN ('requested', 'confirmed', 'assigned', 'on_the_way', 'started', 'completed', 'cancelled', 'rejected') THEN
        NEW.progress := norm_next::public.wash_status;
      END IF;
    ELSIF NEW.progress IS DISTINCT FROM OLD.progress AND NEW.status IS NOT DISTINCT FROM OLD.status THEN
      IF norm_next IN ('confirmed', 'completed', 'cancelled', 'rejected') THEN
        NEW.status := norm_next::public.booking_status;
      ELSIF norm_next = 'requested' THEN
        NEW.status := 'pending'::public.booking_status;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_wash_booking_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_wash_booking_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE s RECORD;
BEGIN
  IF public.has_role(auth.uid(), 'admin') THEN RETURN NEW; END IF;

  SELECT * INTO s FROM public.wash_services WHERE id = NEW.service_id;
  IF s IS NULL OR NOT s.active THEN
    RAISE EXCEPTION 'This wash package is not available';
  END IF;
  IF NEW.slot_date < (now() AT TIME ZONE 'Asia/Kolkata')::date THEN
    RAISE EXCEPTION 'Choose a slot in the future';
  END IF;

  NEW.price := s.price;
  NEW.status := 'pending';
  NEW.payment_status := 'unpaid';
  NEW.payment_method := NULL;
  NEW.paid_at := NULL;
  NEW.razorpay_order_id := NULL;
  NEW.razorpay_payment_id := NULL;
  NEW.assigned_vendor_id := NULL;
  NEW.admin_note := NULL;
  NEW.rejection_reason := NULL;
  NEW.refund_amount := 0;
  NEW.cancelled_at := NULL;
  NEW.cancelled_by := NULL;
  NEW.completed_at := NULL;
  RETURN NEW;
END; $$;


--
-- Name: extension_clashes(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.extension_clashes(_booking_id uuid, _new_end date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.bookings b, public.bookings o
     WHERE b.id = _booking_id AND o.vehicle_id = b.vehicle_id AND o.id <> b.id
       AND o.status IN ('pending','confirmed')
       AND o.start_date <= _new_end AND o.end_date >= b.start_date
  ) OR EXISTS (
    SELECT 1 FROM public.bookings b, public.availability_blocks a
     WHERE b.id = _booking_id AND a.vehicle_id = b.vehicle_id
       AND a.start_date <= _new_end AND a.end_date >= b.start_date
  );
$$;


--
-- Name: generate_scheduled_reminders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_scheduled_reminders() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_inserted int := 0;
  r record;
BEGIN
  -- 1. Bookings pickup in <= 24 hours
  FOR r IN
    SELECT b.id, b.customer_id, b.start_date, b.pickup_time, v.title AS vehicle_title
    FROM public.bookings b
    JOIN public.vehicles v ON b.vehicle_id = v.id
    WHERE b.status = 'confirmed' AND b.payment_status = 'paid'
      AND (b.start_date + b.pickup_time) BETWEEN now() AND (now() + interval '24 hours')
      -- Idempotency: skip if 24h reminder already generated
      AND NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = b.customer_id
          AND n.link = '/bookings'
          AND n.title = 'Trip reminder (24h)'
          AND n.body LIKE '%' || b.id::text || '%'
      )
  LOOP
    INSERT INTO public.notifications (user_id, title, body, link)
    VALUES (
      r.customer_id,
      'Trip reminder (24h)',
      format('Your upcoming trip with %s starts within 24 hours (Ref: %s).', r.vehicle_title, r.id),
      '/bookings'
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  -- 2. Bookings pickup in <= 2 hours
  FOR r IN
    SELECT b.id, b.customer_id, b.start_date, b.pickup_time, v.title AS vehicle_title
    FROM public.bookings b
    JOIN public.vehicles v ON b.vehicle_id = v.id
    WHERE b.status = 'confirmed' AND b.payment_status = 'paid'
      AND (b.start_date + b.pickup_time) BETWEEN now() AND (now() + interval '2 hours')
      -- Idempotency
      AND NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = b.customer_id
          AND n.link = '/bookings'
          AND n.title = 'Pickup in 2 hours'
          AND n.body LIKE '%' || b.id::text || '%'
      )
  LOOP
    INSERT INTO public.notifications (user_id, title, body, link)
    VALUES (
      r.customer_id,
      'Pickup in 2 hours',
      format('Pickup begins shortly for %s (Ref: %s). Check-in opens 30 min before departure.', r.vehicle_title, r.id),
      '/bookings'
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  -- 3. Customer DL expiry within 30 days
  FOR r IN
    SELECT p.id AS user_id, p.dl_expiry
    FROM public.profiles p
    WHERE p.dl_expiry IS NOT NULL
      AND p.dl_expiry BETWEEN CURRENT_DATE AND (CURRENT_DATE + interval '30 days')
      AND NOT EXISTS (
        SELECT 1 FROM public.notifications n
        WHERE n.user_id = p.id
          AND n.title = 'Driving Licence Expiring Soon'
          AND n.created_at >= (now() - interval '15 days')
      )
  LOOP
    INSERT INTO public.notifications (user_id, title, body, link)
    VALUES (
      r.user_id,
      'Driving Licence Expiring Soon',
      format('Your driving licence expires on %s. Please renew and update your document.', r.dl_expiry),
      '/profile'
    );
    v_inserted := v_inserted + 1;
  END LOOP;

  RETURN jsonb_build_object('reminders_created', v_inserted);
END;
$$;


--
-- Name: handle_incident_notifications(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_incident_notifications() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_host_id uuid;
BEGIN
  IF NEW.type = 'sos' THEN
    -- Alert all admins
    INSERT INTO public.notifications (user_id, title, body, link)
    SELECT
      ur.user_id,
      'EMERGENCY SOS Triggered!',
      format('SOS alert reported at %s,%s for booking %s', COALESCE(NEW.lat::text, 'unknown'), COALESCE(NEW.lng::text, 'unknown'), COALESCE(NEW.booking_id::text, 'none')),
      '/admin'
    FROM public.user_roles ur
    WHERE ur.role = 'admin';
  ELSIF NEW.type = 'lost_item' AND NEW.booking_id IS NOT NULL THEN
    -- Look up vehicle host
    SELECT vendor_id INTO v_host_id FROM public.bookings WHERE id = NEW.booking_id;
    IF v_host_id IS NOT NULL THEN
      INSERT INTO public.notifications (user_id, title, body, link)
      VALUES (
        v_host_id,
        'Lost Item Reported',
        format('A customer reported a lost item (%s) on booking %s.', COALESCE(NEW.item_name, 'item'), NEW.booking_id),
        '/bookings'
      );
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.profiles (id, full_name, avatar_url)
  VALUES (NEW.id,
    COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', split_part(NEW.email,'@',1)),
    NEW.raw_user_meta_data->>'avatar_url');
  INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'customer') ON CONFLICT DO NOTHING;
  RETURN NEW;
END; $$;


