-- Name: notify_admins(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_admins(_title text, _body text, _link text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.notifications (user_id, title, body, link)
  SELECT ur.user_id, _title, _body, _link FROM public.user_roles ur WHERE ur.role = 'admin';
END; $$;


--
-- Name: notify_ticket_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_ticket_update() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status = 'Resolved' AND OLD.status != 'Resolved' THEN
      INSERT INTO public.notifications (user_id, title, body, link)
      VALUES (
        NEW.user_id,
        'Support Ticket Resolved',
        format('Your ticket %s (%s) has been marked as resolved.', NEW.ticket_no, NEW.subject),
        '/help'
      );
    END IF;
  ELSIF TG_OP = 'INSERT' AND NEW.is_admin THEN
    -- Admin message on ticket
    INSERT INTO public.notifications (user_id, title, body, link)
    SELECT
      t.user_id,
      'Support Reply',
      format('New reply on ticket %s: %s', t.ticket_no, substring(NEW.message from 1 for 60)),
      '/help'
    FROM public.support_tickets t
    WHERE t.id = NEW.ticket_id;
  END IF;
  RETURN NEW;
END;
$$;


