-- Name: notify_user(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.notify_user(_user_id uuid, _title text, _body text, _link text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF _user_id IS NULL THEN RETURN; END IF;
  INSERT INTO public.notifications (user_id, title, body, link)
  VALUES (_user_id, _title, _body, _link);
END; $$;


--
-- Name: prevent_booking_conflict(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_booking_conflict() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.vehicle_id = NEW.vehicle_id
      AND b.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND b.status IN ('pending','confirmed')
      AND b.start_date <= NEW.end_date
      AND b.end_date >= NEW.start_date
  ) THEN
    RAISE EXCEPTION 'Vehicle not available for selected dates';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.availability_blocks a
    WHERE a.vehicle_id = NEW.vehicle_id
      AND a.start_date <= NEW.end_date
      AND a.end_date >= NEW.start_date
  ) THEN
    RAISE EXCEPTION 'Vehicle is blocked on selected dates';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: prevent_driver_booking_conflict(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_driver_booking_conflict() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE d RECORD;
BEGIN
  SELECT verification_status, status INTO d FROM public.drivers WHERE id = NEW.driver_id;
  IF d IS NULL THEN
    RAISE EXCEPTION 'Driver profile not found';
  END IF;
  IF d.verification_status IS DISTINCT FROM 'approved' OR d.status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'This driver is not available for hire';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.driver_bookings b
    WHERE b.driver_id = NEW.driver_id
      AND b.id <> COALESCE(NEW.id, '00000000-0000-0000-0000-000000000000'::uuid)
      AND b.status IN ('pending','confirmed')
      AND b.start_date <= NEW.end_date
      AND b.end_date >= NEW.start_date
  ) THEN
    RAISE EXCEPTION 'Driver is already booked for the selected dates';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: recompute_driver_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_driver_rating() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE did UUID;
BEGIN
  did := COALESCE(NEW.driver_id, OLD.driver_id);
  UPDATE public.drivers SET
    avg_rating = COALESCE((SELECT AVG(rating)::numeric(3,2) FROM public.driver_reviews WHERE driver_id = did), 0),
    review_count = (SELECT COUNT(*) FROM public.driver_reviews WHERE driver_id = did)
  WHERE id = did;
  UPDATE public.public_drivers SET
    avg_rating = COALESCE((SELECT AVG(rating)::numeric(3,2) FROM public.driver_reviews WHERE driver_id = did), 0),
    review_count = (SELECT COUNT(*) FROM public.driver_reviews WHERE driver_id = did)
  WHERE id = did;
  RETURN NEW;
END; $$;


--
-- Name: recompute_vehicle_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_vehicle_rating() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE vid UUID;
BEGIN
  vid := COALESCE(NEW.vehicle_id, OLD.vehicle_id);
  UPDATE public.vehicles SET
    avg_rating = COALESCE((SELECT AVG(rating)::numeric(3,2) FROM public.reviews WHERE vehicle_id = vid), 0),
    review_count = (SELECT COUNT(*) FROM public.reviews WHERE vehicle_id = vid)
  WHERE id = vid;
  RETURN NEW;
END; $$;


--
-- Name: recompute_wash_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recompute_wash_rating() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _cleaner_id uuid;
  _center_id uuid;
BEGIN
  _cleaner_id := COALESCE(NEW.cleaner_id, OLD.cleaner_id);
  _center_id := COALESCE(NEW.center_id, OLD.center_id);

  -- Recompute for cleaner if assigned
  IF _cleaner_id IS NOT NULL THEN
    UPDATE public.cleaners
       SET avg_rating = COALESCE((SELECT ROUND(AVG(rating)::numeric, 2) FROM public.wash_reviews WHERE cleaner_id = _cleaner_id), 0),
           review_count = (SELECT COUNT(*) FROM public.wash_reviews WHERE cleaner_id = _cleaner_id),
           updated_at = now()
     WHERE id = _cleaner_id;
  END IF;

  -- Recompute for wash center if assigned
  IF _center_id IS NOT NULL THEN
    UPDATE public.wash_centers
       SET avg_rating = COALESCE((SELECT ROUND(AVG(rating)::numeric, 2) FROM public.wash_reviews WHERE center_id = _center_id), 0),
           review_count = (SELECT COUNT(*) FROM public.wash_reviews WHERE center_id = _center_id),
           updated_at = now()
     WHERE id = _center_id;
  END IF;

  RETURN NEW;
END;
$$;


