--
-- Name: rental_base_price(uuid, date, date, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rental_base_price(_vehicle_id uuid, _start_date date, _end_date date, _pickup time without time zone, _dropoff time without time zone) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v RECORD; hours numeric; rem numeric; weeks numeric := 0; days numeric; subtotal numeric := 0;
BEGIN
  SELECT price_hourly, price_daily, price_weekly INTO v FROM public.vehicles WHERE id = _vehicle_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not found'; END IF;
  hours := EXTRACT(EPOCH FROM ((_end_date + _dropoff) - (_start_date + _pickup))) / 3600.0;
  IF hours IS NULL OR hours <= 0 THEN RAISE EXCEPTION 'Drop-off must be after pickup'; END IF;

  IF hours < 24 AND COALESCE(v.price_hourly, 0) > 0 THEN
    RETURN ceil(hours) * v.price_hourly;
  END IF;

  rem := ceil(hours);
  IF COALESCE(v.price_weekly, 0) > 0 AND rem >= 168 THEN
    weeks := floor(rem / 168);
    subtotal := weeks * v.price_weekly;
    rem := rem - weeks * 168;
  END IF;
  days := ceil(rem / 24.0);
  IF days > 0 THEN subtotal := subtotal + days * COALESCE(v.price_daily, 0); END IF;
  RETURN subtotal;
END; $$;


--
-- Name: report_review(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.report_review(_review_id uuid, _reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;
  IF _reason IS NULL OR length(btrim(_reason)) = 0 THEN
    RAISE EXCEPTION 'Reason required';
  END IF;
  UPDATE public.reviews
    SET reported = true,
        report_reason = left(btrim(_reason), 500)
    WHERE id = _review_id;
END;
$$;


--
-- Name: request_booking_extension(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_booking_extension(_booking_id uuid, _hours integer, _note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b RECORD; new_end timestamp; extra numeric; ch jsonb; ext_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.bookings WHERE id = _booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF b.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your booking'; END IF;
  IF b.status <> 'confirmed' OR b.payment_status <> 'paid' THEN RAISE EXCEPTION 'Only paid, confirmed trips can be extended'; END IF;
  IF b.pickup_checked_at IS NULL OR b.return_checked_at IS NOT NULL THEN RAISE EXCEPTION 'Extensions are only possible during an active trip'; END IF;
  IF _hours IS NULL OR _hours < 1 OR _hours > 72 THEN RAISE EXCEPTION 'Extend by 1 to 72 hours'; END IF;
  IF EXISTS (SELECT 1 FROM public.booking_extensions WHERE booking_id = b.id AND status IN ('pending','accepted')) THEN
    RAISE EXCEPTION 'An extension request is already open for this trip';
  END IF;

  new_end := (b.end_date + b.dropoff_time) + make_interval(hours => _hours);
  IF public.extension_clashes(b.id, new_end::date) THEN
    RAISE EXCEPTION 'The vehicle is not available for the extra time';
  END IF;

  -- Price the whole new window and charge the difference, so tiered
  -- hourly/daily/weekly pricing stays consistent. Never negative.
  extra := GREATEST(0, public.rental_base_price(b.vehicle_id, b.start_date, new_end::date, b.pickup_time, new_end::time) - b.base_price);
  ch := public.compute_charges(extra, NULL);

  INSERT INTO public.booking_extensions (
    booking_id, customer_id, vendor_id, hours, note, new_end_date, new_dropoff_time,
    extra_base, service_fee, gst_amount, commission_amount, commission_gst, provider_earning, extra_total)
  VALUES (
    b.id, b.customer_id, b.vendor_id, _hours, NULLIF(btrim(COALESCE(_note, '')), ''), new_end::date, new_end::time,
    extra, (ch->>'service_fee')::numeric, (ch->>'gst')::numeric, (ch->>'commission')::numeric,
    (ch->>'commission_gst')::numeric, (ch->>'provider_earning')::numeric, (ch->>'customer_total')::numeric)
  RETURNING id INTO ext_id;

  PERFORM public.notify_user(b.vendor_id, 'Trip extension requested',
    'Your guest wants to extend their trip by ' || _hours || 'h. Accept or decline it.',
    '/bookings/' || b.id || '/trip');
  RETURN ext_id;
END; $$;


--
-- Name: request_withdrawal(numeric, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_withdrawal(_amount numeric, _method text, _upi_id text DEFAULT NULL::text, _account_name text DEFAULT NULL::text, _account_number text DEFAULT NULL::text, _ifsc text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE uid uuid := auth.uid(); s RECORD; avail numeric; wid uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.vendors WHERE id = uid)
     AND NOT EXISTS (SELECT 1 FROM public.drivers WHERE id = uid)
     AND NOT EXISTS (SELECT 1 FROM public.cleaners WHERE id = uid)
     AND NOT EXISTS (SELECT 1 FROM public.wash_centers WHERE id = uid) THEN
    RAISE EXCEPTION 'Only hosts, drivers, cleaners and washing centers can withdraw earnings';
  END IF;
  SELECT * INTO s FROM public.platform_settings WHERE id = 1;
  _amount := round(COALESCE(_amount, 0), 2);
  IF _amount < COALESCE(s.min_withdrawal, 0) OR _amount <= 0 THEN
    RAISE EXCEPTION 'Minimum withdrawal is Rs %', s.min_withdrawal;
  END IF;

  -- Serialise concurrent requests from the same user.
  PERFORM 1 FROM public.wallets WHERE user_id = uid FOR UPDATE;
  avail := public.withdrawable_balance(uid);
  IF _amount > avail THEN RAISE EXCEPTION 'You can withdraw at most Rs %', avail; END IF;

  IF _method = 'upi' THEN
    IF COALESCE(btrim(_upi_id), '') !~ '^[A-Za-z0-9._-]{2,}@[A-Za-z]{2,}$' THEN
      RAISE EXCEPTION 'Enter a valid UPI ID';
    END IF;
  ELSIF _method = 'bank' THEN
    IF COALESCE(btrim(_account_name), '') = '' THEN RAISE EXCEPTION 'Enter the account holder name'; END IF;
    IF COALESCE(btrim(_account_number), '') !~ '^[0-9]{9,18}$' THEN RAISE EXCEPTION 'Enter a valid account number'; END IF;
    IF upper(COALESCE(btrim(_ifsc), '')) !~ '^[A-Z]{4}0[A-Z0-9]{6}$' THEN RAISE EXCEPTION 'Enter a valid IFSC code'; END IF;
  ELSE
    RAISE EXCEPTION 'Choose UPI or bank transfer';
  END IF;

  INSERT INTO public.withdrawals (user_id, amount, method, upi_id, account_name, account_number, ifsc)
  VALUES (uid, _amount, _method,
          CASE WHEN _method = 'upi' THEN btrim(_upi_id) END,
          CASE WHEN _method = 'bank' THEN btrim(_account_name) END,
          CASE WHEN _method = 'bank' THEN btrim(_account_number) END,
          CASE WHEN _method = 'bank' THEN upper(btrim(_ifsc)) END)
  RETURNING id INTO wid;

  PERFORM public.wallet_apply(uid, -_amount, 'payout', NULL, wid::text, 'Withdrawal requested');
  PERFORM public.notify_admins('New withdrawal request', 'Rs ' || _amount || ' via ' || _method || ' — review in Payouts.', '/admin');
  RETURN wid;
END; $_$;


--
-- Name: sync_public_driver(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_public_driver() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.verification_status = 'approved' AND NEW.status = 'active' THEN
    INSERT INTO public.public_drivers (
      id, full_name, city, bio, experience_years, languages, vehicle_types,
      photo_url, hourly_rate, daily_rate, avg_rating, review_count, created_at, updated_at,
      trip_types, service_area
    )
    VALUES (
      NEW.id, NEW.full_name, NEW.city, NEW.bio, NEW.experience_years, NEW.languages, NEW.vehicle_types,
      NEW.photo_url, NEW.hourly_rate, NEW.daily_rate, NEW.avg_rating, NEW.review_count, NEW.created_at, now(),
      COALESCE(NEW.trip_types, '{}'), NEW.service_area
    )
    ON CONFLICT (id) DO UPDATE SET
      full_name = EXCLUDED.full_name,
      city = EXCLUDED.city,
      bio = EXCLUDED.bio,
      experience_years = EXCLUDED.experience_years,
      languages = EXCLUDED.languages,
      vehicle_types = EXCLUDED.vehicle_types,
      photo_url = EXCLUDED.photo_url,
      hourly_rate = EXCLUDED.hourly_rate,
      daily_rate = EXCLUDED.daily_rate,
      avg_rating = EXCLUDED.avg_rating,
      review_count = EXCLUDED.review_count,
      trip_types = EXCLUDED.trip_types,
      service_area = EXCLUDED.service_area,
      updated_at = now();
  ELSE
    DELETE FROM public.public_drivers WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END; $$;


