    ELSIF NEW.dl_status = 'rejected' THEN
      PERFORM public.notify_user(NEW.id, 'Licence rejected',
        COALESCE(NEW.dl_rejection_reason, 'Please upload clearer licence photos.'), '/profile');
    END IF;
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: tg_notify_vehicle_verification(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_notify_vehicle_verification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
