--
-- Name: tg_notify_wash_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_notify_wash_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM public.notify_admins('New wash request',
      NEW.city || ' · ' || NEW.slot_date || ' ' || NEW.slot_time || ' — assign a washer partner.', '/admin');
    PERFORM public.notify_user(NEW.customer_id, 'Wash requested', 'Our team is checking washer availability.', '/washes');
    RETURN NEW;
  END IF;

  IF (NEW.status IS DISTINCT FROM OLD.status OR NEW.progress IS DISTINCT FROM OLD.progress) THEN
    IF NEW.progress = 'on_the_way' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Cleaner on the way', 'Your cleaner is heading to your address.', '/washes');
    ELSIF NEW.progress = 'started' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Wash started', 'Your vehicle wash is now in progress.', '/washes');
    ELSIF NEW.status = 'confirmed' OR NEW.progress = 'confirmed' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Wash slot approved', 'Pay now to confirm your doorstep wash.', '/washes');
    ELSIF NEW.status = 'rejected' OR NEW.progress = 'rejected' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Wash slot unavailable',
        COALESCE(NEW.rejection_reason, 'No washer partner is free for that slot.'), '/wash');
    ELSIF NEW.status = 'cancelled' OR NEW.progress = 'cancelled' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Wash cancelled',
        CASE WHEN NEW.refund_amount > 0 THEN 'Refund of Rs ' || NEW.refund_amount || ' credited to your wallet.' ELSE 'Your wash booking was cancelled.' END, '/washes');
    ELSIF NEW.status = 'completed' OR NEW.progress = 'completed' THEN
      PERFORM public.notify_user(NEW.customer_id, 'Wash completed', 'Your vehicle is sparkling. View your invoice.', '/washes');
    END IF;
  END IF;

  IF NEW.payment_status = 'paid' AND OLD.payment_status IS DISTINCT FROM 'paid' THEN
    PERFORM public.notify_user(NEW.customer_id, 'Wash payment successful', 'Your slot is locked in.', '/washes');
  END IF;

  RETURN NEW;
END; $$;


--
-- Name: tg_price_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_price_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE ch jsonb; base numeric; dep numeric;
BEGIN
  base := public.rental_base_price(NEW.vehicle_id, NEW.start_date, NEW.end_date, NEW.pickup_time, NEW.dropoff_time);
  SELECT COALESCE(security_deposit, 0) INTO dep FROM public.vehicles WHERE id = NEW.vehicle_id;
  ch := public.compute_charges(base, NEW.coupon_code);
  NEW.base_price := base;
  NEW.security_deposit := dep;
  NEW.coupon_code := ch->>'coupon_code';
  NEW.discount := (ch->>'discount')::numeric;
  NEW.service_fee := (ch->>'service_fee')::numeric;
  NEW.gst_amount := (ch->>'gst')::numeric;
  NEW.commission_amount := (ch->>'commission')::numeric;
  NEW.commission_gst := (ch->>'commission_gst')::numeric;
  NEW.provider_earning := (ch->>'provider_earning')::numeric;
  NEW.total_price := (ch->>'customer_total')::numeric + dep;
  NEW.payment_status := 'unpaid';
  NEW.paid_at := NULL;
  NEW.earning_credited_at := NULL;
  NEW.refund_amount := 0;
  RETURN NEW;
END; $$;


--
-- Name: tg_price_driver_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_price_driver_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE ch jsonb; p RECORD;
BEGIN
  SELECT * INTO p FROM public.driver_base_price(NEW.driver_id, NEW.rate_type::text, NEW.start_date, NEW.end_date, NEW.start_time, NEW.end_time);
  ch := public.compute_charges(p.base, NEW.coupon_code);
  NEW.hours := p.billed_hours;
  NEW.days := p.billed_days;
  NEW.base_price := p.base;
  NEW.coupon_code := ch->>'coupon_code';
  NEW.discount := (ch->>'discount')::numeric;
  NEW.service_fee := (ch->>'service_fee')::numeric;
  NEW.gst_amount := (ch->>'gst')::numeric;
  NEW.commission_amount := (ch->>'commission')::numeric;
  NEW.commission_gst := (ch->>'commission_gst')::numeric;
  NEW.provider_earning := (ch->>'provider_earning')::numeric;
  NEW.total_price := (ch->>'customer_total')::numeric;
  NEW.payment_status := 'unpaid';
  NEW.paid_at := NULL;
  NEW.earning_credited_at := NULL;
  NEW.refund_amount := 0;
  RETURN NEW;
END; $$;


--
-- Name: tg_price_wash_booking(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_price_wash_booking() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE ch jsonb; base numeric;
BEGIN
  SELECT price INTO base FROM public.wash_services WHERE id = NEW.service_id AND active;
  IF base IS NULL THEN RAISE EXCEPTION 'Wash service not available'; END IF;
  ch := public.compute_charges(base, NEW.coupon_code);
  NEW.base_price := base;
  NEW.coupon_code := ch->>'coupon_code';
  NEW.discount := (ch->>'discount')::numeric;
  NEW.service_fee := (ch->>'service_fee')::numeric;
  NEW.gst_amount := (ch->>'gst')::numeric;
  NEW.commission_amount := (ch->>'commission')::numeric;
  NEW.commission_gst := (ch->>'commission_gst')::numeric;
  NEW.provider_earning := (ch->>'provider_earning')::numeric;
  NEW.price := (ch->>'customer_total')::numeric;
  NEW.payment_status := 'unpaid';
  NEW.paid_at := NULL;
  NEW.earning_credited_at := NULL;
  NEW.refund_amount := 0;
  RETURN NEW;
END; $$;


--
-- Name: tg_set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;


--
-- Name: tg_wash_settle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tg_wash_settle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE payee uuid;
BEGIN
  IF NEW.status = 'completed' AND OLD.status IS DISTINCT FROM 'completed'
     AND NEW.payment_status = 'paid' AND NEW.earning_credited_at IS NULL THEN
    payee := COALESCE(NEW.assigned_cleaner_id,
                      (SELECT id FROM public.wash_centers WHERE id = NEW.assigned_vendor_id));
    IF payee IS NOT NULL AND payee <> NEW.customer_id AND COALESCE(NEW.provider_earning, 0) > 0 THEN
      PERFORM public.wallet_apply(payee, NEW.provider_earning, 'wash_earning', NULL, NEW.id::text,
        'Earning from completed wash (after commission)');
    END IF;
    NEW.earning_credited_at := now();
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: validate_and_fill_wash_review(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_and_fill_wash_review() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  b record;
BEGIN
  SELECT * INTO b
    FROM public.wash_bookings
   WHERE id = NEW.wash_booking_id;

  IF b IS NULL THEN
    RAISE EXCEPTION 'Wash booking not found';
  END IF;

  IF b.status != 'completed' AND b.progress != 'completed' THEN
    RAISE EXCEPTION 'Only completed wash bookings can be reviewed';
  END IF;

  IF NEW.customer_id IS NULL THEN
    NEW.customer_id := auth.uid();
  END IF;

  IF NEW.customer_id != b.customer_id AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only the customer who booked the wash can write a review';
  END IF;

  -- Auto-populate provider relations from the booking if not explicitly provided
  IF NEW.cleaner_id IS NULL AND b.assigned_cleaner_id IS NOT NULL THEN
    NEW.cleaner_id := b.assigned_cleaner_id;
  END IF;

  IF NEW.center_id IS NULL AND b.assigned_vendor_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.wash_centers WHERE id = b.assigned_vendor_id) THEN
      NEW.center_id := b.assigned_vendor_id;
    END IF;
  END IF;

  IF NEW.vendor_id IS NULL THEN
    NEW.vendor_id := b.assigned_vendor_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_coupon(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_coupon(_code text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT COALESCE(
    (SELECT jsonb_build_object(
       'valid', true,
       'code', c.code,
       'percent_off', c.percent_off,
       'amount_off', c.amount_off)
     FROM public.coupons c
     WHERE upper(btrim(c.code)) = upper(btrim(_code))
       AND c.active
       AND (c.starts_at IS NULL OR c.starts_at <= now())
       AND (c.ends_at IS NULL OR c.ends_at >= now())
     LIMIT 1),
    jsonb_build_object('valid', false)
  );
$$;


--
-- Name: validate_pool_rating(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_pool_rating() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_trip record;
  v_is_driver boolean;
  v_is_passenger boolean;
BEGIN
  -- Check trip exists and is completed
  SELECT id, driver_id, status INTO v_trip
  FROM public.pool_trips
  WHERE id = NEW.trip_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Trip not found';
  END IF;

  IF v_trip.status <> 'completed' THEN
    RAISE EXCEPTION 'Ratings can only be submitted for completed trips (trip status is %)', v_trip.status;
  END IF;

  -- Validate participant roles
  IF NEW.role = 'passenger_to_driver' THEN
    IF NEW.ratee_id <> v_trip.driver_id THEN
      RAISE EXCEPTION 'Ratee must be the trip driver';
    END IF;
    -- Verify rater had a confirmed/completed request on this trip
    PERFORM 1 FROM public.pool_requests
    WHERE trip_id = NEW.trip_id
      AND passenger_id = NEW.rater_id
      AND status IN ('confirmed', 'completed');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Rater is not a confirmed passenger on this trip';
    END IF;

  ELSIF NEW.role = 'driver_to_passenger' THEN
    IF NEW.rater_id <> v_trip.driver_id THEN
      RAISE EXCEPTION 'Rater must be the trip driver';
    END IF;
    -- Verify ratee had a confirmed/completed request on this trip
    PERFORM 1 FROM public.pool_requests
    WHERE trip_id = NEW.trip_id
      AND passenger_id = NEW.ratee_id
      AND status IN ('confirmed', 'completed');
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Ratee is not a confirmed passenger on this trip';
    END IF;
  ELSE
    RAISE EXCEPTION 'Invalid rating role %', NEW.role;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: verify_cleaner(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_cleaner(_cleaner_id uuid, _decision text, _rejection_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can verify cleaners';
  END IF;

  IF _decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Invalid decision: %', _decision;
  END IF;

  UPDATE public.cleaners
     SET verification_status = _decision::verification_status,
         rejection_reason = CASE WHEN _decision = 'rejected' THEN _rejection_reason ELSE NULL END,
         updated_at = now()
   WHERE id = _cleaner_id;

  IF _decision = 'approved' THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (_cleaner_id, 'cleaner')
    ON CONFLICT DO NOTHING;
  END IF;
END;
$$;


--
-- Name: verify_wash_center(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_wash_center(_center_id uuid, _decision text, _rejection_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Only admins can verify wash centers';
  END IF;

  IF _decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Invalid decision: %', _decision;
  END IF;

  UPDATE public.wash_centers
     SET verification_status = _decision::verification_status,
         rejection_reason = CASE WHEN _decision = 'rejected' THEN _rejection_reason ELSE NULL END,
         active = CASE WHEN _decision = 'approved' THEN true ELSE false END,
         updated_at = now()
   WHERE id = _center_id;

  IF _decision = 'approved' THEN
    INSERT INTO public.user_roles (user_id, role)
    VALUES (_center_id, 'wash_center')
    ON CONFLICT DO NOTHING;

    INSERT INTO public.wash_vendors (id, name, city, contact_phone, contact_email, daily_capacity, active)
    SELECT id, name, city, contact_phone, contact_email, daily_capacity, true
    FROM public.wash_centers WHERE id = _center_id
    ON CONFLICT (id) DO UPDATE SET
      name = EXCLUDED.name,
      city = EXCLUDED.city,
      contact_phone = EXCLUDED.contact_phone,
      contact_email = EXCLUDED.contact_email,
      daily_capacity = EXCLUDED.daily_capacity,
      active = true;
  END IF;
END;
$$;


--
-- Name: wallet_apply(uuid, numeric, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wallet_apply(_user_id uuid, _amount numeric, _kind text, _booking_id uuid DEFAULT NULL::uuid, _reference text DEFAULT NULL::text, _description text DEFAULT NULL::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE new_balance numeric;
BEGIN
  INSERT INTO public.wallets (user_id) VALUES (_user_id) ON CONFLICT (user_id) DO NOTHING;
  UPDATE public.wallets SET balance = balance + _amount WHERE user_id = _user_id RETURNING balance INTO new_balance;
  IF new_balance IS NULL THEN RAISE EXCEPTION 'Wallet not found'; END IF;
  IF new_balance < 0 THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF;
  INSERT INTO public.wallet_transactions (user_id, amount, kind, balance_after, booking_id, reference, description)
  VALUES (_user_id, _amount, _kind, new_balance, _booking_id, _reference, _description);
  RETURN new_balance;
END; $$;


--
-- Name: wallet_pay_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wallet_pay_booking(_booking_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b RECORD; bal numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.bookings WHERE id = _booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF b.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your booking'; END IF;
  IF b.status <> 'confirmed' THEN RAISE EXCEPTION 'Host has not accepted this booking yet'; END IF;
  IF b.payment_status = 'paid' THEN RAISE EXCEPTION 'Already paid'; END IF;

  INSERT INTO public.wallets (user_id) VALUES (b.customer_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id FOR UPDATE;
  IF bal < b.total_price THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF;

  PERFORM public.wallet_apply(b.customer_id, -b.total_price, 'booking_payment', b.id, NULL, 'Payment for booking');
  UPDATE public.bookings
     SET payment_status = 'paid', paid_at = now(), payment_method = 'wallet'
   WHERE id = b.id;

  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id;
  RETURN bal;
END; $$;


--
-- Name: wallet_pay_driver_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wallet_pay_driver_booking(_driver_booking_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b RECORD; bal numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.driver_bookings WHERE id = _driver_booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Booking not found'; END IF;
  IF b.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your booking'; END IF;
  IF b.status <> 'confirmed' THEN RAISE EXCEPTION 'Driver has not accepted this request yet'; END IF;
  IF b.payment_status = 'paid' THEN RAISE EXCEPTION 'Already paid'; END IF;

  INSERT INTO public.wallets (user_id) VALUES (b.customer_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id FOR UPDATE;
  IF bal < b.total_price THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF;

  PERFORM public.wallet_apply(b.customer_id, -b.total_price, 'driver_payment', NULL, b.id::text, 'Payment for driver hire');
  UPDATE public.driver_bookings
     SET payment_status = 'paid', paid_at = now(), payment_method = 'wallet'
   WHERE id = b.id;

  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id;
  RETURN bal;
END; $$;


--
-- Name: wallet_pay_extension(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wallet_pay_extension(_extension_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE e RECORD; b RECORD; bal numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO e FROM public.booking_extensions WHERE id = _extension_id FOR UPDATE;
  IF e IS NULL THEN RAISE EXCEPTION 'Extension not found'; END IF;
  IF e.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your request'; END IF;
  IF e.status = 'paid' THEN RAISE EXCEPTION 'Already paid'; END IF;
  IF e.status <> 'accepted' THEN RAISE EXCEPTION 'The host has not accepted this extension'; END IF;
  SELECT * INTO b FROM public.bookings WHERE id = e.booking_id FOR UPDATE;
  IF b.status <> 'confirmed' OR b.return_checked_at IS NOT NULL THEN RAISE EXCEPTION 'This trip has already ended'; END IF;

  IF e.extra_total > 0 THEN
    PERFORM public.wallet_apply(e.customer_id, -e.extra_total, 'booking_payment', b.id, NULL,
      'Trip extension +' || e.hours || 'h');
  END IF;

  -- trg_bookings_conflict re-checks availability here; a clash raises and
  -- rolls back the wallet debit too. The host's share is released with the
  -- rest of provider_earning when the trip completes (trg_money_settle).
  UPDATE public.bookings SET
    end_date = e.new_end_date,
    dropoff_time = e.new_dropoff_time,
    base_price = base_price + e.extra_base,
    service_fee = service_fee + e.service_fee,
    gst_amount = gst_amount + e.gst_amount,
    commission_amount = commission_amount + e.commission_amount,
    commission_gst = commission_gst + e.commission_gst,
    provider_earning = provider_earning + e.provider_earning,
    total_price = total_price + e.extra_total
  WHERE id = b.id;

  UPDATE public.booking_extensions SET status = 'paid', paid_at = now() WHERE id = e.id;

  PERFORM public.notify_user(e.vendor_id, 'Trip extended',
    'The guest paid for +' || e.hours || 'h. New return: ' || to_char(e.new_end_date + e.new_dropoff_time, 'DD Mon HH24:MI') || '.',
    '/bookings/' || b.id || '/trip');

  SELECT balance INTO bal FROM public.wallets WHERE user_id = e.customer_id;
  RETURN COALESCE(bal, 0);
END; $$;


--
-- Name: wallet_pay_wash_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.wallet_pay_wash_booking(_wash_booking_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE b RECORD; bal numeric;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  SELECT * INTO b FROM public.wash_bookings WHERE id = _wash_booking_id FOR UPDATE;
  IF b IS NULL THEN RAISE EXCEPTION 'Wash booking not found'; END IF;
  IF b.customer_id <> auth.uid() THEN RAISE EXCEPTION 'Not your booking'; END IF;
  IF b.status <> 'confirmed' THEN RAISE EXCEPTION 'Admin has not approved this wash yet'; END IF;
  IF b.payment_status = 'paid' THEN RAISE EXCEPTION 'Already paid'; END IF;

  INSERT INTO public.wallets (user_id) VALUES (b.customer_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id FOR UPDATE;
  IF bal < b.price THEN RAISE EXCEPTION 'Insufficient wallet balance'; END IF;

  PERFORM public.wallet_apply(b.customer_id, -b.price, 'wash_payment', NULL, b.id::text, 'Payment for vehicle wash');

  UPDATE public.wash_bookings
     SET payment_status = 'paid', paid_at = now(), payment_method = 'wallet'
   WHERE id = b.id;

  SELECT balance INTO bal FROM public.wallets WHERE user_id = b.customer_id;
  RETURN bal;
END; $$;


--
-- Name: withdrawable_balance(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.withdrawable_balance(_user uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE uid uuid := COALESCE(_user, auth.uid()); bal numeric; earned numeric; withdrawn numeric;
BEGIN
  IF uid IS NULL THEN RETURN 0; END IF;
  IF uid <> auth.uid() AND NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Not allowed';
  END IF;
  SELECT COALESCE(balance, 0) INTO bal FROM public.wallets WHERE user_id = uid;
  SELECT COALESCE(sum(amount), 0) INTO earned FROM public.wallet_transactions
   WHERE user_id = uid AND kind IN ('booking_earning','driver_earning','driver_refund_reversal','wash_earning');
  SELECT COALESCE(sum(amount), 0) INTO withdrawn FROM public.withdrawals
   WHERE user_id = uid AND status <> 'rejected';
  RETURN GREATEST(0, LEAST(COALESCE(bal, 0), earned - withdrawn));
END; $$;


--
-- Name: foldername(text); Type: FUNCTION; Schema: storage; Owner: -
--

CREATE FUNCTION storage.foldername(name text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT (string_to_array(name, '/'))[1:cardinality(string_to_array(name, '/')) - 1]
$$;


