  WHERE ((v.id = reviews.vehicle_id) AND (v.vendor_id = auth.uid()))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM public.vehicles v
  WHERE ((v.id = reviews.vehicle_id) AND (v.vendor_id = auth.uid())))) AND (vendor_response IS NOT NULL)));


--
-- Name: vehicles Vendor updates own vehicle; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Vendor updates own vehicle" ON public.vehicles FOR UPDATE USING (((auth.uid() = vendor_id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));


--
-- Name: vendors Vendor updates self; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Vendor updates self" ON public.vendors FOR UPDATE USING (((auth.uid() = id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));


--
-- Name: vehicle_maintenance Vendors manage own vehicle maintenance; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Vendors manage own vehicle maintenance" ON public.vehicle_maintenance TO authenticated USING (((auth.uid() = vendor_id) OR public.has_role(auth.uid(), 'admin'::public.app_role))) WITH CHECK (((auth.uid() = vendor_id) OR public.has_role(auth.uid(), 'admin'::public.app_role)));


--
-- Name: wash_bookings Wash bookings access policy; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Wash bookings access policy" ON public.wash_bookings FOR SELECT TO authenticated USING (((customer_id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role) OR (assigned_cleaner_id = auth.uid()) OR (assigned_vendor_id = auth.uid()) OR ((assigned_cleaner_id IS NULL) AND (assigned_vendor_id IS NULL) AND ((status = 'confirmed'::public.booking_status) OR (progress = 'confirmed'::public.wash_status)) AND (EXISTS ( SELECT 1
   FROM public.cleaners c
  WHERE ((c.id = auth.uid()) AND (c.verification_status = 'approved'::public.verification_status) AND (lower(TRIM(BOTH FROM c.city)) = lower(TRIM(BOTH FROM wash_bookings.city)))))))));


--
-- Name: wash_centers Wash centers manage own profile; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Wash centers manage own profile" ON public.wash_centers TO authenticated USING (((id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role))) WITH CHECK (((id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role)));


--
-- Name: wash_centers Wash centers view profiles; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Wash centers view profiles" ON public.wash_centers FOR SELECT TO authenticated USING (((id = auth.uid()) OR public.has_role(auth.uid(), 'admin'::public.app_role) OR (verification_status = 'approved'::public.verification_status)));


--
-- Name: wash_reviews Wash reviews are public; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Wash reviews are public" ON public.wash_reviews FOR SELECT TO anon, authenticated USING (true);


